-- Cloudflare D1 schema for MUDARRIS JOIN
CREATE TABLE IF NOT EXISTS teachers (id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,display_name TEXT NOT NULL,password_hash TEXT,google_sub TEXT UNIQUE,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY,teacher_id TEXT NOT NULL,expires_at INTEGER NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS invited_users (email TEXT PRIMARY KEY,invited_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS school_admins (email TEXT PRIMARY KEY,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS games (id INTEGER PRIMARY KEY AUTOINCREMENT,teacher_id TEXT NOT NULL,title TEXT NOT NULL,subject TEXT DEFAULT '',grade TEXT DEFAULT '',description TEXT DEFAULT '',settings TEXT DEFAULT '{}',created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS questions (id INTEGER PRIMARY KEY AUTOINCREMENT,game_id INTEGER NOT NULL,position INTEGER NOT NULL,question_type TEXT NOT NULL DEFAULT 'quiz',prompt TEXT NOT NULL,options TEXT NOT NULL DEFAULT '[]',correct_answer TEXT DEFAULT '',time_limit INTEGER DEFAULT 20,points INTEGER DEFAULT 1000,media_url TEXT DEFAULT '',UNIQUE(game_id,position));
CREATE TABLE IF NOT EXISTS classes (id INTEGER PRIMARY KEY AUTOINCREMENT,teacher_id TEXT NOT NULL,name TEXT NOT NULL,grade TEXT DEFAULT '',join_code TEXT NOT NULL UNIQUE,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS class_students (id INTEGER PRIMARY KEY AUTOINCREMENT,class_id INTEGER NOT NULL,name TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS live_sessions (id INTEGER PRIMARY KEY AUTOINCREMENT,pin TEXT NOT NULL UNIQUE,game_id INTEGER NOT NULL,teacher_id TEXT NOT NULL,mode TEXT NOT NULL DEFAULT 'classic',status TEXT NOT NULL DEFAULT 'waiting',current_question INTEGER DEFAULT -1,question_started_at INTEGER,started_at TEXT,finished_at TEXT,join_locked INTEGER DEFAULT 0,paused_at INTEGER,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS players (id INTEGER PRIMARY KEY AUTOINCREMENT,session_id INTEGER NOT NULL,nickname TEXT NOT NULL,avatar TEXT DEFAULT 'tiger',score INTEGER DEFAULT 0,streak INTEGER DEFAULT 0,last_answered_question INTEGER DEFAULT -1,joined_at TEXT DEFAULT CURRENT_TIMESTAMP,UNIQUE(session_id,nickname));
CREATE TABLE IF NOT EXISTS answers (id INTEGER PRIMARY KEY AUTOINCREMENT,session_id INTEGER NOT NULL,player_id INTEGER NOT NULL,question_position INTEGER NOT NULL,answer TEXT NOT NULL,correct INTEGER DEFAULT 0,points INTEGER DEFAULT 0,response_ms INTEGER DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP,UNIQUE(player_id,question_position));
CREATE INDEX IF NOT EXISTS games_teacher_idx ON games(teacher_id,updated_at);
CREATE INDEX IF NOT EXISTS players_session_idx ON players(session_id,score);